<?php
declare(strict_types=1);
namespace Workspace;
require dirname(__DIR__).'/app/bootstrap.php';
$dir=sys_get_temp_dir().'/cw-deploy-'.bin2hex(random_bytes(8));mkdir($dir,0700);putenv('WORKSPACE_DATA='.$dir);putenv('WORKSPACE_DB=sqlite');
$n=0;function dcheck(bool $ok,string $label):void{global $n;if(!$ok)throw new \RuntimeException($label);$n++;}
function ddeny(callable $fn,string $label):void{try{$fn();}catch(Problem){dcheck(true,$label);return;}throw new \RuntimeException('Expected denial: '.$label);}
function dclean(string $dir):void{foreach(new \FilesystemIterator($dir) as $f){if($f->isDir()&&!$f->isLink())dclean($f->getPathname());else unlink($f->getPathname());}rmdir($dir);}
try{
$db=database(true);addUser($db,'owner@example.test','Owner','owner','sample-password-only',true);addUser($db,'dev@example.test','Dev','developer','sample-password-only');$owner=organizationUser($db,['id'=>1,'name'=>'Owner']);$dev=organizationUser($db,['id'=>2,'name'=>'Dev']);$p=createProject($db,$owner,bin2hex(random_bytes(16)),['title'=>'Project','kind'=>'oss']);$other=createProject($db,$owner,bin2hex(random_bytes(16)),['title'=>'Other','kind'=>'internal']);changeMembership($db,$owner,'project',$p,2,true);
$repo=insertId($db,'INSERT INTO github_repositories(project_id,repository_id,installation_id,full_name) VALUES(?,?,?,?)',[$p,40,30,'owner/example']);$digest=str_repeat('b',64);$sha=str_repeat('a',40);$e=json_encode(['artifact'=>['name'=>'app.zip','sha256'=>$digest,'size'=>123]],JSON_THROW_ON_ERROR);$hash=hash('sha256',$e);
$r=insertId($db,"INSERT INTO project_releases(project_id,repository_binding,repository_generation,tag,commit_sha,changelog,artifact_name,artifact_sha256,required_checks,responsible_id,creator_id,request_key,created_at,state,evidence,evidence_hash,verified_at,confirmed_at,confirmed_by) VALUES(?,?,1,?,?,?,?,?, ?,1,1,?,1,'confirmed',?,?,1,1,1)",[$p,$repo,'v1',$sha,'Notes','app.zip',$digest,'["Build"]',bin2hex(random_bytes(16)),$e,$hash]);
$host=insertId($db,"INSERT INTO infra_hosts(organization_id,name,panel_key,panel_target,panel_hash,panel_api,servers_key,servers_target,servers_hash,workspace_uuid,asset_uuid) VALUES(1,'Host','panel',?,?,'v2','servers',?,?,?,?)",[str_repeat('a',64),str_repeat('b',64),str_repeat('c',64),str_repeat('d',64),str_repeat('e',36),str_repeat('f',36)]);$env=insertId($db,"INSERT INTO infra_environments(organization_id,project_id,kind,name) VALUES(1,?,'prod','Production')",[$p]);$site=insertId($db,"INSERT INTO infra_sites(organization_id,project_id,environment_id,host_id,remote_id,site_name) VALUES(1,?,?,?,1,'example.test')",[$p,$env,$host]);query($db,"INSERT INTO infra_operation_owners VALUES(?,'site.deploy','aapanel',1)",[$host]);
$in=['site_id'=>$site,'release_id'=>$r,'window_start'=>gmdate('Y-m-d\TH:i',time()-60),'window_end'=>gmdate('Y-m-d\TH:i',time()+3600)];$key=bin2hex(random_bytes(16));$id=deploymentCreate($db,$owner,$p,$key,$in);dcheck($id===deploymentCreate($db,$owner,$p,$key,$in),'idempotent');ddeny(fn()=>deploymentCreate($db,$owner,$p,bin2hex(random_bytes(16)),$in),'active site');ddeny(fn()=>deploymentCreate($db,$dev,$p,bin2hex(random_bytes(16)),$in),'developer denied');ddeny(fn()=>deploymentCreate($db,$owner,$other,bin2hex(random_bytes(16)),$in),'cross project');
$fake=fn($job,$recover)=>['state'=>'rolled_back','before'=>str_repeat('c',40),'after'=>str_repeat('c',40),'message'=>'rollback verified'];dcheck(deploymentRun($db,$id,false,$fake)['state']==='rolled_back','result persisted');ddeny(fn()=>deploymentRun($db,$id,false,$fake),'repeat execution denied');
$id2=deploymentCreate($db,$owner,$p,bin2hex(random_bytes(16)),$in);query($db,"UPDATE infra_operation_owners SET provider='servers' WHERE host_id=? AND operation='site.deploy'",[$host]);dcheck(deploymentRun($db,$id2,false,$fake)['state']==='failed','changed owner route blocked');query($db,"UPDATE infra_operation_owners SET provider='aapanel' WHERE host_id=? AND operation='site.deploy'",[$host]);
$id3=deploymentCreate($db,$owner,$p,bin2hex(random_bytes(16)),$in);dcheck(deploymentRun($db,$id3,false,fn()=>throw new \RuntimeException('worker stopped'))['state']==='recovery_required','unknown result blocks');ddeny(fn()=>deploymentCreate($db,$owner,$p,bin2hex(random_bytes(16)),$in),'cannot bypass recovery');dcheck(deploymentRun($db,$id3,true,$fake)['state']==='rolled_back','recovered');
$id4=deploymentCreate($db,$owner,$p,bin2hex(random_bytes(16)),$in);deploymentCancel($db,$owner,$p,$id4);dcheck(entity($db,'SELECT state FROM deployments WHERE id=?',[$id4])['state']==='cancelled','cancel');
require ROOT.'/app/Web.php';$_SESSION=['csrf'=>'test'];ob_start();pageView('deployments','Деплой',$owner,deploymentPage($db,$owner,$p));$html=ob_get_clean();dcheck(str_contains($html,'rolled_back')&&str_contains($html,'example.test'),'render');
if(in_array('--postgres',$argv,true)){$report=migrateToPostgres($dir.'/source.sqlite');$pg=postgresConnect();dcheck($report['tables']['deployments']['rows']===4&&count(deploymentPage($pg,$owner,$p)['deployments'])===4,'PostgreSQL transfer');$pg=null;}
echo "OK · $n deployment DB checks\n";
}finally{$db=null;dclean($dir);}
